// Non-PDF files are logged (not silently dropped) so nothing in the Inbox goes unnoticed.
const cfg = $('Config').first().json;
const now = DateTime.now().setZone(cfg.timezone || 'America/New_York');
return {
  json: {
    date_processed: now.toFormat('yyyy-MM-dd'),
    processed_at: now.toFormat('yyyy-MM-dd HH:mm:ss ZZZZ'),
    file_name: $json.name || '',
    source_file_id: $json.id || '',
    status: 'Skipped - Not a PDF',
    notes: `Not processed: file type is ${$json.mimeType || 'unknown'}, only PDFs are read`,
  },
};

// Runs once per poll/backfill. Skips any PDF whose Drive file ID is already in the
// Invoice Log, before a Gemini call is spent on it.
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const loggedIds = new Set(rows.map(r => String(r['Source File ID'] ?? '').trim()).filter(Boolean));
const seen = new Set();
const out = [];
for (const f of $('Is PDF?').all(0)) {
  const id = String(f.json.id ?? '').trim();
  let reason = '';
  if (!id) reason = 'No Drive file ID on trigger item';
  else if (loggedIds.has(id)) reason = 'Already in Invoice Log (same Drive file ID)';
  else if (seen.has(id)) reason = 'Same file listed twice in this run';
  if (id) seen.add(id);
  out.push({
    json: {
      file_id: id,
      file_name: f.json.name ?? '',
      mime_type: f.json.mimeType ?? '',
      already_logged: reason !== '',
      skip_reason: reason,
    },
    pairedItem: { item: 0 },
  });
}
return out;

// All three Gemini models failed (HTTP error, or an answer with no usable content).
// Builds the alert; the PDF stays in the Inbox, unlogged, so Reprocess Inbox can retry it.
const cfg = $('Config').first().json;
const now = DateTime.now().setZone(cfg.timezone || 'America/New_York');
let src = {};
try { src = $('Check File ID Logged').item.json || {}; } catch (e) { src = {}; }
const j = $json || {};
let error;
if (j.error) {
  const e = j.error;
  error = typeof e === 'string' ? e : [e.message, e.description].filter(Boolean).join(' - ') || JSON.stringify(e);
} else if (j.candidates || j.promptFeedback) {
  const c = (Array.isArray(j.candidates) && j.candidates[0]) || {};
  error = `Gemini answered but returned no usable content (${(j.promptFeedback && j.promptFeedback.blockReason) || c.finishReason || 'empty response'})`;
} else {
  error = JSON.stringify(j).slice(0, 500) || 'Unknown error';
}
return {
  json: {
    file_id: src.file_id || '(unknown)',
    file_name: src.file_name || '(unknown)',
    drive_link: src.file_id ? `https://drive.google.com/file/d/${src.file_id}/view` : '',
    error: String(error).slice(0, 1000),
    models_tried: 'Gemini 3.5 Flash Lite, Gemini 3.1 Flash Lite, Gemini 3.7 Flash',
    failed_at: now.toFormat('yyyy-MM-dd HH:mm:ss ZZZZ'),
  },
};

// Turns Gemini's reply into typed fields. This node never throws: an empty, blocked or
// non-JSON reply becomes parse_error, which Validate Invoice turns into a Needs Review row.
const FIELDS = ['vendor', 'invoice_number', 'invoice_date', 'due_date', 'due_date_note', 'subtotal', 'tax', 'total'];
const MODEL_BY_NODE = {
  'Has Content? (3.5 Flash Lite)': 'Gemini 3.5 Flash Lite',
  'Has Content? (3.1 Flash Lite)': 'Gemini 3.1 Flash Lite',
  'Has Content? (3.7 Flash)': 'Gemini 3.7 Flash',
};
let src = {};
try { src = $('Check File ID Logged').item.json || {}; } catch (e) { src = {}; }
let prev = '';
try { prev = $prevNode.name; } catch (e) { prev = ''; }
const res = $json || {};
const model = MODEL_BY_NODE[prev] || res.modelVersion || prev || 'unknown';

const candidate = (Array.isArray(res.candidates) && res.candidates[0]) || {};
const parts = (candidate.content && Array.isArray(candidate.content.parts)) ? candidate.content.parts : [];
const raw = parts.map(p => (p && typeof p.text === 'string' ? p.text : '')).join('').trim();

let fields = {};
let parseError = '';
if (!raw) {
  const why = (res.promptFeedback && res.promptFeedback.blockReason) || candidate.finishReason || 'empty response';
  parseError = `AI returned no content (${why})`;
} else {
  const text = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try {
    let parsed = JSON.parse(text);
    if (Array.isArray(parsed) && parsed.length === 1) parsed = parsed[0];
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) fields = parsed;
    else parseError = 'AI response was JSON but not a single invoice object';
  } catch (e) {
    parseError = `AI response was not valid JSON (${e.message})`;
  }
}

const out = {};
for (const k of FIELDS) out[k] = fields[k] === undefined ? null : fields[k];
return {
  json: {
    ...out,
    source_file_id: src.file_id || null,
    source_file_name: src.file_name || null,
    model_used: model,
    parse_error: parseError || null,
    raw_response_excerpt: parseError ? raw.slice(0, 300) : null,
  },
};

// Deterministic accountant-style checks. Sets status OK / Needs Review, notes, the new
// file name, and the processed date/time in the client's time zone (Config.timezone).
const cfg = $('Config').first().json;
const now = DateTime.now().setZone(cfg.timezone || 'America/New_York');
const inv = { ...$json };
const issues = [];
const LABEL = { vendor: 'Vendor', invoice_number: 'Invoice #', invoice_date: 'Invoice Date', due_date: 'Due Date', subtotal: 'Subtotal', tax: 'Tax', total: 'Total' };
const isBlank = v => v === null || v === undefined || String(v).trim() === '';
const toAmount = v => {
  if (isBlank(v)) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : NaN;
  const n = Number(String(v).replace(/[$,\s]/g, ''));
  return Number.isFinite(n) ? n : NaN;
};
const isIsoDate = s => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && DateTime.fromISO(s).isValid;
const clean = s => String(s || '').replace(/[^A-Za-z0-9]+/g, '');
let newName;

if (inv.parse_error) {
  issues.push(`${inv.parse_error}. Enter this invoice manually`);
  newName = inv.source_file_name || `UNREADABLE_${inv.source_file_id || 'file'}.pdf`;
} else {
  for (const k of ['subtotal', 'tax', 'total']) {
    const n = toAmount(inv[k]);
    if (Number.isNaN(n)) { issues.push(`${LABEL[k]} is not a number ("${inv[k]}")`); inv[k] = null; inv[`${k}_unreadable`] = true; }
    else inv[k] = n;
  }
  for (const k of ['vendor', 'invoice_number', 'invoice_date', 'total']) {
    if (isBlank(inv[k]) && !inv[`${k}_unreadable`]) issues.push(`Missing ${LABEL[k]}`);
  }
  for (const k of ['invoice_date', 'due_date']) {
    if (!isBlank(inv[k]) && !isIsoDate(String(inv[k]))) issues.push(`${LABEL[k]} is not a valid YYYY-MM-DD date ("${inv[k]}")`);
  }
  if (inv.total !== null) {
    if (inv.subtotal !== null && inv.tax !== null) {
      const expected = Math.round((inv.subtotal + inv.tax) * 100) / 100;
      if (Math.abs(expected - inv.total) > 0.01 + 1e-9) {
        issues.push(`Total mismatch: subtotal + tax = ${expected.toFixed(2)}, invoice says ${Number(inv.total).toFixed(2)}`);
      }
    } else {
      const missing = [inv.subtotal === null ? 'Subtotal' : null, inv.tax === null ? 'Tax' : null].filter(Boolean);
      issues.push(`Cannot verify total: missing ${missing.join(' and ')}`);
    }
  }
  if (isBlank(inv.due_date)) issues.push(inv.due_date_note ? `No due date (${inv.due_date_note})` : 'Missing Due Date');
  const month = isIsoDate(inv.invoice_date) ? inv.invoice_date.slice(0, 7) : 'UNDATED';
  newName = `${month}_${clean(inv.vendor) || 'UnknownVendor'}_${clean(inv.invoice_number) || 'NOINV'}.pdf`;
}
delete inv.subtotal_unreadable; delete inv.tax_unreadable; delete inv.total_unreadable;

return {
  json: {
    ...inv,
    date_processed: now.toFormat('yyyy-MM-dd'),
    processed_at: now.toFormat('yyyy-MM-dd HH:mm:ss ZZZZ'),
    status: issues.length ? 'Needs Review' : 'OK',
    notes: issues.join('; '),
    new_file_name: newName,
    drive_link: inv.source_file_id ? `https://drive.google.com/file/d/${inv.source_file_id}/view` : '',
  },
};

// Second dedupe pass, after extraction: same normalized vendor + invoice # already in the
// Invoice Log (or earlier in this same run) = duplicate. Duplicates are not logged,
// renamed, moved or emailed.
const SUFFIXES = new Set(['inc', 'llc', 'ltd', 'co', 'corp', 'corporation', 'company', 'pc', 'pllc', 'llp', 'lp']);
const normVendor = v => {
  const t = String(v ?? '').toLowerCase().replace(/&/g, ' and ').split(/[^a-z0-9]+/).filter(Boolean);
  while (t.length > 1 && SUFFIXES.has(t[t.length - 1])) t.pop();
  return t.join('');
};
const normInvoice = v => String(v ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '').replace(/^0+(?=.)/, '');
const keyOf = (vendor, inv) => {
  const nv = normVendor(vendor), ni = normInvoice(inv);
  return nv && ni ? `${nv}|${ni}` : null;
};

const rows = $('Read Invoice Log').all(0).map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const loggedIds = new Set(rows.map(r => String(r['Source File ID'] ?? '').trim()).filter(Boolean));
const loggedKeys = new Map();
for (const r of rows) {
  const k = keyOf(r['Vendor'], r['Invoice #']);
  if (k && !loggedKeys.has(k)) loggedKeys.set(k, r.row_number ?? '?');
}

// Keys accepted earlier in this execution. The fallback chain can make this node run more
// than once per execution, so they are kept in workflow static data, tagged by execution id.
const sd = $getWorkflowStaticData('global');
if (sd.dedupeExecutionId !== $execution.id) { sd.dedupeExecutionId = $execution.id; sd.dedupeKeys = []; }
const runKeys = new Set(sd.dedupeKeys);

return $input.all().map((item, i) => {
  const inv = item.json;
  const fid = String(inv.source_file_id ?? '').trim();
  const key = inv.parse_error ? null : keyOf(inv.vendor, inv.invoice_number);
  let reason = '';
  if (fid && loggedIds.has(fid)) reason = 'Already in Invoice Log (same Drive file ID)';
  else if (key && loggedKeys.has(key)) reason = `Already in Invoice Log: same vendor + invoice # (sheet row ${loggedKeys.get(key)})`;
  else if (key && runKeys.has(key)) reason = 'Same vendor + invoice # appeared earlier in this run';
  if (!reason && key) { runKeys.add(key); sd.dedupeKeys.push(key); }
  return { json: { ...inv, dedupe_key: key, is_duplicate: reason !== '', duplicate_reason: reason }, pairedItem: { item: i } };
});
